from fastapi import FastAPI, Depends
from fastapi.dependencies import Query
from functools import wraps
from typing import ForwardRef, List, Any
import pytest
import inspect

# We need to define the type here to avoid NameError in the forward ref
# in a real scenario this might be in another module
class Item:
    pass

def wrapped_method(item: "Item"):
    return item

@wraps(wrapped_method)
def wrapper(item: "Item"):
    return wrapped_method(item)

app = FastAPI()

@app.get("/")
def read_root(item: Item = Depends(wrapper)):
    return {"item": item}

def test_wrapped_method_type_inference():
    from fastapi.dependencies.utils import get_typed_signature

    # This is what FastAPI does internally
    sig = get_typed_signature(wrapper)

    # Check if the parameter 'item' has the correct type 'Item'
    param = sig.parameters["item"]
    assert param.annotation is Item
